typedef struct {
    char name[8];
    int score;
} Player;

void player_init(Player *p, const char *name, int score) {
    size_t i = 0;
    while (i < sizeof p->name - 1 && name[i] != '\0') {
        p->name[i] = name[i];
        i++;
    }
    p->name[i] = '\0';
    p->score = score;
}

Player player_bumped(Player p, int bonus) {
    p.score += bonus;
    return p;
}

int best_index(const Player *list, size_t n) {
    if (n == 0) {
        return -1;
    }
    size_t best = 0;
    for (size_t i = 1; i < n; i++) {
        if (list[i].score > list[best].score) {
            best = i;
        }
    }
    return (int)best;
}

