#include <stdbool.h>
#include <stdint.h>

int popcount32(uint32_t x) {
    int n = 0;
    while (x != 0) {
        x &= x - 1u;
        n++;
    }
    return n;
}

bool is_pow2(uint32_t x) {
    return x != 0 && (x & (x - 1u)) == 0;
}

uint32_t set_field(uint32_t word, unsigned lo, unsigned width, uint32_t value) {
    uint32_t mask = ((UINT32_C(1) << width) - 1u) << lo;
    return (word & ~mask) | ((value << lo) & mask);
}

