#include <stdio.h>

struct node {
    int v;
    const struct node *next;
};

static int order = 0;
static int has_v[8];
static int rec_v[8];
static int rec_ret[8];
static int rec_order[8];
static int calls = 0;

static int alt(const struct node *n, int depth) {
    int r;
    calls++;
    if (n == NULL) {
        has_v[depth] = 0;
        r = 0;
    } else {
        has_v[depth] = 1;
        rec_v[depth] = n->v;
        r = n->v - alt(n->next, depth + 1);
    }
    rec_ret[depth] = r;
    rec_order[depth] = ++order;
    return r;
}

int main(void) {
    struct node d = {7, NULL};
    struct node c = {2, &d};
    struct node b = {9, &c};
    struct node a = {4, &b};
    const char *names[5] = {"alt(&a)", "alt(&b)", "alt(&c)", "alt(&d)", "alt(NULL)"};
    alt(&a, 0);
    for (int k = 0; k < calls; k++) {
        if (has_v[k]) {
            printf("%s\t%d\t%d\t%d\n", names[k], rec_v[k], rec_ret[k], rec_order[k]);
        } else {
            printf("%s\t-\t%d\t%d\n", names[k], rec_ret[k], rec_order[k]);
        }
    }
    return 0;
}

